 "<b style=\"font-size:24px;color:#4b5d73\">Capas</b><br><span style=\"font-size:20px;color:#2a2a26\">4 chaquetas, abrigos o chalecos.</span>": "<b style=\"font-size:24px;color:#4b5d73\">Lagen</b><br><span style=\"font-size:20px;color:#2a2a26\">4 jasjes, jassen of gilets.</span>",
 "<b style=\"font-size:24px;color:#7a8f6b\">Calzado</b><br><span style=\"font-size:20px;color:#2a2a26\">3 pares versátiles.</span>": "<b style=\"font-size:24px;color:#7a8f6b\">Schoenen</b><br><span style=\"font-size:20px;color:#2a2a26\">3 veelzijdige paar.</span>",
 "<b style=\"font-size:24px;color:#b5651d\">Un vestido o traje</b><br><span style=\"font-size:20px;color:#2a2a26\">2 para ocasiones especiales.</span>": "<b style=\"font-size:24px;color:#b5651d\">Een jurk of pak</b><br><span style=\"font-size:20px;color:#2a2a26\">2 voor bijzondere gelegenheden.</span>",
